-- Hand-written: integrity backstops Prisma cannot express. The tenant pattern repeats the
-- kernel's single rule (parseTenantId); the others repeat the module's domain rules.
ALTER TABLE "objects"."object_definition"
  ADD CONSTRAINT "object_definition_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "object_definition_key_check" CHECK ("key" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "object_definition_name_check" CHECK (char_length(btrim("name")) > 0),
  ADD CONSTRAINT "object_definition_status_check" CHECK (
    "status" IN ('draft', 'published', 'retired')
    AND ("status" = 'draft') = ("published_revision_id" IS NULL)
  ),
  ADD CONSTRAINT "object_definition_version_check" CHECK ("version" >= 1 AND "revision_count" >= 0);

ALTER TABLE "objects"."object_revision"
  ADD CONSTRAINT "object_revision_number_check" CHECK ("number" >= 1),
  ADD CONSTRAINT "object_revision_content_hash_check" CHECK ("content_hash" ~ '^sha256:[0-9a-f]{64}$'),
  -- MAX_FIELDS (128) fields of bounded size: well under 1 MiB.
  ADD CONSTRAINT "object_revision_fields_check" CHECK (
    jsonb_typeof("fields") = 'array' AND octet_length("fields"::text) <= 1048576
  );

ALTER TABLE "objects"."object_record"
  ADD CONSTRAINT "object_record_revision_hash_check" CHECK ("revision_hash" ~ '^sha256:[0-9a-f]{64}$'),
  -- At most 128 values of at most 10000 characters each, plus the sealed part.
  ADD CONSTRAINT "object_record_values_check" CHECK (
    jsonb_typeof("values") = 'object' AND octet_length("values"::text) <= 6291456
  ),
  ADD CONSTRAINT "object_record_sealed_check" CHECK (octet_length("sealed") <= 6291456),
  ADD CONSTRAINT "object_record_version_check" CHECK ("version" >= 1);

-- Grants. The group role "phoenix_app" is created by the cluster bootstrap, never by a
-- migration. A revision is immutable (V1): INSERT and SELECT only. A definition is retired,
-- never removed. A record is deleted with its subject key (ADR-0017 decision 4).
GRANT USAGE ON SCHEMA "objects" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("name", "status", "published_revision_id", "revision_count", "version", "updated_at") ON TABLE "objects"."object_definition" TO "phoenix_app";
GRANT SELECT, INSERT ON TABLE "objects"."object_revision" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE, UPDATE ("revision_id", "revision_hash", "values", "sealed", "version", "updated_at") ON TABLE "objects"."object_record" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced, with the reference policy of
-- platform.isolation_probe on every table.
ALTER TABLE "objects"."object_definition" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "objects"."object_definition" FORCE ROW LEVEL SECURITY;
CREATE POLICY "object_definition_tenant_isolation" ON "objects"."object_definition"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "objects"."object_revision" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "objects"."object_revision" FORCE ROW LEVEL SECURITY;
CREATE POLICY "object_revision_tenant_isolation" ON "objects"."object_revision"
