ALTER TABLE "objects"."object_record" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "objects"."object_record" FORCE ROW LEVEL SECURITY;
CREATE POLICY "object_record_tenant_isolation" ON "objects"."object_record"
